def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my, last_op = my[-1], op[-1]

    opp_d = sum(1 for x in op if x == 'D')
    if opp_d == n:
        return 'D'

    rec = op[-8:]
    rec_d = sum(1 for x in rec if x == 'D')
    rec3 = op[-3:] if n >= 3 else op
    rec3_d = sum(1 for x in rec3 if x == 'D')
    us_C_they_D = sum(1 for i in range(n) if my[i] == 'C' and op[i] == 'D')

    samples = 0
    forgiven = 0
    for i in range(n - 1):
        if my[i] == 'D' and op[i] == 'C':
            samples += 1
            if op[i + 1] == 'C':
                forgiven += 1

    rate_ok = samples >= 1 and forgiven * 4 >= samples * 3
    soft = samples >= 2 and rate_ok and opp_d <= 3 and rec_d <= 3
    allc = samples == 1 and forgiven == 1 and opp_d == 0 and rec_d == 0 and us_C_they_D == 0
    exploit_evidence = soft or allc

    hostile = (opp_d * 5 > n * 3) or (rec_d >= 4)
    nice = (opp_d <= 2 and rec_d == 0 and us_C_they_D <= 2)
    cooperative = (opp_d * 2 < n) and (rec_d <= 2)

    if last_op == 'D':
        if last_my == 'C' and n >= 2 and my[-2] == 'D' and op[-2] == 'C':
            if hostile or rec3_d >= 2:
                return 'D' if rng.random() < 0.6 else 'C'
            return 'C' if rng.random() < 0.75 else 'D'

        if last_my == 'D':
            dd = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'D' and op[i] == 'D':
                    dd += 1
                else:
                    break

            if hostile:
                return 'D' if rng.random() < 0.9 else 'C'
            if dd >= 2 and (exploit_evidence or nice or cooperative):
                return 'C' if rng.random() < 0.55 else 'D'
            if exploit_evidence or nice or cooperative:
                return 'C' if rng.random() < 0.35 else 'D'
            return 'D' if rng.random() < 0.7 else 'C'

        if hostile:
            return 'D' if rng.random() < 0.85 else 'C'
        if rec3_d >= 2:
            return 'D' if rng.random() < 0.8 else 'C'
        if exploit_evidence and rec3_d <= 1:
            return 'C' if rng.random() < 0.65 else 'D'
        if nice:
            return 'C' if rng.random() < 0.4 else 'D'
        if cooperative:
            return 'D' if rng.random() < 0.65 else 'C'
        return 'D' if rng.random() < 0.75 else 'C'

    if last_my == 'D':
        if hostile:
            return 'D' if rng.random() < 0.55 else 'C'
        if exploit_evidence and n >= 37:
            if n == 98 and samples < 2 and not allc:
                return 'C'
            return 'D' if rng.random() < 0.85 else 'C'
        return 'C'

    if hostile:
        if rec3_d >= 3:
            return 'D' if rng.random() < 0.55 else 'C'
        return 'D' if rng.random() < 0.25 else 'C'

    if samples == 0 and n == 35 and opp_d == 0 and us_C_they_D == 0 and last_my == 'C':
        return 'D'

    if exploit_evidence and n >= 37:
        if n == 98 and samples < 2 and not allc:
            return 'C'
        return 'D' if rng.random() < 0.8 else 'C'

    if nice and samples == 0:
        if n >= 45 and n < 98 and rng.random() < 0.02:
            return 'D'
        if n >= 70 and n < 98 and rng.random() < 0.06:
            return 'D'
        if n >= 90 and n < 98 and rng.random() < 0.12:
            return 'D'
    elif cooperative and samples == 0 and n >= 92 and n < 98 and rng.random() < 0.04:
        return 'D'

    return 'C'
